# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DESCRIBING PEOPLE: APPEARANCE vs. PERSONALITY (ENG.6.3)</text>\n  <rect x="20" y="48" width="320" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Physical Appearance (Dış Görünüş)</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#2563eb">Soru: What does he / she look like?</text>\n  <text x="180" y="122" text-anchor="middle" font-size="11" fill="#1e3a8a">• Height/Build (is): tall, short, medium-height,</text>\n  <text x="180" y="140" text-anchor="middle" font-size="11" fill="#1e3a8a">slim, thin, well-built, plump, overweight</text>\n  <text x="180" y="164" text-anchor="middle" font-size="11" fill="#1e3a8a">• Hair/Eyes (has got): long wavy brown hair,</text>\n  <text x="180" y="182" text-anchor="middle" font-size="11" fill="#1e3a8a">short curly blonde hair, hazel / green eyes</text>\n  <text x="180" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">She is tall and slim. She has got green eyes.</text>\n\n  <rect x="360" y="48" width="320" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Personality Traits (Kişilik Özellikleri)</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">Soru: What is he / she like?</text>\n  <text x="520" y="122" text-anchor="middle" font-size="11" fill="#14532d">• Positive: generous (cömert), honest (dürüst),</text>\n  <text x="520" y="140" text-anchor="middle" font-size="11" fill="#14532d">helpful, cheerful, outgoing, polite, punctual</text>\n  <text x="520" y="164" text-anchor="middle" font-size="11" fill="#14532d">• Other: shy (utangaç), stubborn (inatçı),</text>\n  <text x="520" y="182" text-anchor="middle" font-size="11" fill="#14532d">selfish (bencil), forgetful (unutkan), calm</text>\n  <text x="520" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">He is generous, honest and very helpful.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">COMPARATIVE ADJECTIVES (KARŞILAŞTIRMA SIFATLARI VE KURALLARI)</text>\n  <rect x="20" y="48" width="210" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Short Adjectives (+er)</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11" fill="#1e3a8a">• tall ➔ taller than</text>\n  <text x="125" y="120" text-anchor="middle" font-size="11" fill="#1e3a8a">• young ➔ younger than</text>\n  <text x="125" y="142" text-anchor="middle" font-size="11" fill="#1e3a8a">• slim ➔ slimmer than (2x m)</text>\n  <text x="125" y="164" text-anchor="middle" font-size="11" fill="#1e3a8a">• big ➔ bigger than (2x g)</text>\n  <text x="125" y="186" text-anchor="middle" font-size="11" fill="#1e3a8a">• happy ➔ happier than (-ier)</text>\n  <text x="125" y="214" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#2563eb">Ali is taller than Can.</text>\n\n  <rect x="245" y="48" width="210" height="192" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">2. Long Adjectives (more ...)</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11" fill="#581c87">• generous ➔ more generous</text>\n  <text x="350" y="120" text-anchor="middle" font-size="11" fill="#581c87">• outgoing ➔ more outgoing</text>\n  <text x="350" y="142" text-anchor="middle" font-size="11" fill="#581c87">• hardworking ➔ more hardworking</text>\n  <text x="350" y="164" text-anchor="middle" font-size="11" fill="#581c87">• punctual ➔ more punctual</text>\n  <text x="350" y="186" text-anchor="middle" font-size="11" fill="#581c87">• beautiful ➔ more beautiful</text>\n  <text x="350" y="214" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#6b21a8">Ece is more outgoing than Su.</text>\n\n  <rect x="470" y="48" width="210" height="192" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#c2410c">3. Irregular (Düzensiz)</text>\n  <text x="575" y="102" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9a3412">• good ➔ better than</text>\n  <text x="575" y="126" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9a3412">• bad ➔ worse than</text>\n  <text x="575" y="150" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9a3412">• far ➔ farther / further</text>\n  <text x="575" y="174" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9a3412">• little ➔ less than</text>\n  <text x="575" y="214" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#c2410c">Sharing is better than being selfish.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">CLOTHING, ACCESSORIES AND WEATHER CONDITIONS</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="182" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">1. Clothes and Accessories</text>\n  <text x="182" y="102" text-anchor="middle" font-size="11" fill="#155e75">• Winter / Cold: coat, jacket, sweater, jumper,</text>\n  <text x="182" y="120" text-anchor="middle" font-size="11" fill="#155e75">scarf (atkı), gloves (eldiven), boots, beanie</text>\n  <text x="182" y="146" text-anchor="middle" font-size="11" fill="#155e75">• Summer / Warm: T-shirt, shorts, dress, skirt,</text>\n  <text x="182" y="164" text-anchor="middle" font-size="11" fill="#155e75">sandals, trainers, sunglasses, cap</text>\n  <text x="182" y="206" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">What is she wearing? ➔ She is wearing a coat.</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="517" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">2. Adjective Order &amp; Describing</text>\n  <text x="517" y="102" text-anchor="middle" font-size="11" fill="#9d174d">• Sıfat Sıralaması (Saç Betimleme):</text>\n  <text x="517" y="122" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#be185d">Uzunluk (Size) + Şekil (Shape) + Renk (Colour)</text>\n  <text x="517" y="146" text-anchor="middle" font-size="11" fill="#9d174d">• «long straight black hair» (uzun düz siyah saç)</text>\n  <text x="517" y="166" text-anchor="middle" font-size="11" fill="#9d174d">• «short wavy brown hair» (kısa dalgalı kahverengi)</text>\n  <text x="517" y="206" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">Who is the boy in the blue jumper?</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
